paid=tiers.filter(q=>q.a>0),ps=priceState(e),priceSub={free:"Free plan only",freemium:"Free plan plus paid plans",fm:"Free plan plus paid plans",paid:"Paid plans only",unk:"Price not confirmed"}[ps],
