linkObjs=[{u:e.website,label:"Official website"}].concat((e.sources||[]).filter(u=>u!==e.website).map(u=>({u,label:u==="https://gemini.google/gp/mac/?hl=en"?"Mac app":hostOf(u)}))).concat((e.social||[]).map(s=>({u:s.url,label:"Other"===s.label?hostOf(s.url):s.label}))).concat(x?[["privacyUrl","Privacy policy"],["termsUrl","Terms"],["docsUrl","Docs"],["pricingUrl","Pricing page"]].filter(k=>x[k[0]]&&/^https:\/\//.test(x[k[0]])).map(k=>({u:x[k[0]],label:k[1]})):[]),
